"use strict";

/**
 * getDefaultHttpStepConfig — returns Synthetics step configuration.
 * Replace with your actual step config.
 */
function getDefaultHttpStepConfig() {
  return {
    includeRequestHeaders:  true,
    includeResponseHeaders: true,
    includeRequestBody:     true,
    includeResponseBody:    true,
    restrictedHeaders:      ["Authorization", "Cookie"],
  };
}

module.exports = { getDefaultHttpStepConfig };
